using UnityEngine;
using UnityEditor;
using System.IO;

public static class RampGenerator
{
    const int W = 256;
    const int H = 1;
    static string dir = "Assets/Flynn/Textures";

    static void Save(Texture2D tex, string name)
    {
        var bytes = tex.EncodeToPNG();
        var path = Path.Combine(dir, name + ".png");
        File.WriteAllBytes(path, bytes);
        AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
        var importer = AssetImporter.GetAtPath(path) as TextureImporter;
        if (importer != null)
        {
            importer.textureType = TextureImporterType.Default;
            importer.sRGBTexture = true;
            importer.filterMode = FilterMode.Bilinear;
            importer.wrapMode = TextureWrapMode.Clamp;
            importer.npotScale = TextureImporterNPOTScale.None;
            importer.SaveAndReimport();
        }
        Debug.Log($"Saved ramp: {path}");
    }

    static Color Eval(AnimationCurve r, AnimationCurve g, AnimationCurve b, float t)
    {
        return new Color(r.Evaluate(t), g.Evaluate(t), b.Evaluate(t), 1f);
    }

    static AnimationCurve C(params float[] pairs)
    {
        var curve = new AnimationCurve();
        for (int i = 0; i < pairs.Length; i += 2)
            curve.AddKey(new Keyframe(pairs[i], pairs[i + 1]));
        return curve;
    }

    [MenuItem("Tools/Generate Color Ramps")]
    public static void Generate()
    {
        // 1. Warm Sunset — warm shadows, orange mids, golden highlights
        {
            var r = C(0f,0.12f, 0.25f,0.35f, 0.5f,0.85f, 0.75f,1f, 1f,1f);
            var g = C(0f,0.04f, 0.25f,0.12f, 0.5f,0.45f, 0.75f,0.75f, 1f,0.92f);
