using UnityEditor;
using UnityEngine;

public class RampImportFix
{
    [MenuItem("Tools/Fix Ramp Imports")]
    public static void Fix()
    {
        string[] ramps = System.IO.Directory.GetFiles("Assets/Flynn/Textures", "ColorRamp_*.png");
        foreach (var path in ramps)
        {
            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer == null) continue;
            bool changed = false;
            if (importer.textureType != TextureImporterType.Default)
            { importer.textureType = TextureImporterType.Default; changed = true; }
            if (!importer.sRGBTexture)
            { importer.sRGBTexture = true; changed = true; }
            if (importer.filterMode != FilterMode.Bilinear)
            { importer.filterMode = FilterMode.Bilinear; changed = true; }
            if (importer.wrapMode != TextureWrapMode.Clamp)
            { importer.wrapMode = TextureWrapMode.Clamp; changed = true; }
            if (importer.npotScale != TextureImporterNPOTScale.None)
            { importer.npotScale = TextureImporterNPOTScale.None; changed = true; }
            if (changed) { importer.SaveAndReimport(); Debug.Log($"Fixed: {path}"); }
            else Debug.Log($"OK: {path}");
        }
        Debug.Log("Done!");
    }
}

