// Generate a combined preview: all ramps stacked as 32px-tall bars in one image
string[] names = { "Default", "WarmSunset", "CoolTwilight", "Forest", "RetroNeon", "Sepia", "Frost", "Lava", "Pastel" };
string dir = "Assets/Flynn/Textures";
int W = 256, barH = 32, pad = 4, labelH = 16;
int totalH = names.Length * (barH + labelH + pad);
var tex = new Texture2D(W, totalH, TextureFormat.RGBA32, false);
Color bg = new Color(0.15f, 0.15f, 0.15f, 1f);
for (int y = 0; y < totalH; y++)
    for (int x = 0; x < W; x++)
        tex.SetPixel(x, y, bg);

for (int i = 0; i < names.Length; i++)
{
    var rampPath = Path.Combine(dir, $"ColorRamp_{names[i]}.png");
    var rampBytes = File.ReadAllBytes(rampPath);
    var rampTex = new Texture2D(256, 1, TextureFormat.RGB24, false);
    rampTex.LoadImage(rampBytes);
    int yStart = i * (barH + labelH + pad);
    // Draw label region as slightly lighter bg
    for (int lx = 0; lx < W; lx++)
        for (int ly = 0; ly < labelH; ly++)
            tex.SetPixel(lx, yStart + ly, new Color(0.25f, 0.25f, 0.25f, 1f));
    // Draw ramp bars
    for (int lx = 0; lx < W; lx++)
    {
        Color c = rampTex.GetPixel(lx, 0);
        for (int ly = 0; ly < barH; ly++)
            tex.SetPixel(lx, yStart + labelH + ly, c);
    }
    Object.DestroyImmediate(rampTex);
    Debug.Log($"Drew bar for {names[i]} at y={yStart}");
}
tex.Apply();
var outBytes = tex.EncodeToPNG();
var outPath = Path.Combine(dir, "ColorRamp_AllPreview.png");
File.WriteAllBytes(outPath, outBytes);
Object.DestroyImmediate(tex);
AssetDatabase.ImportAsset(outPath, ImportAssetOptions.ForceUpdate);
Debug.Log($"Saved preview: {outPath}");

